<template>

	<div class='item_status' :class="className">
		<div class="item_status_img">
			<img :src="statusImgName" alt="">
		</div>
		<div class='item_status_text_com_warp'>
			<div class="item_status_text_content normal_font">
				{{ text }}
			</div>
		</div>
	</div>

</template>

<script setup>
import { computed } from 'vue'
import zxIcon0 from '@/assets/images/zx0.png'
import zxIcon1 from '@/assets/images/zx1.png'

import lxIcon0 from '@/assets/images/lx0.png'
import lxIcon1 from '@/assets/images/lx1.png'

import gzIcon0 from '@/assets/images/gz0.png'
import gzIcon1 from '@/assets/images/gz1.png'

import jxIcon0 from '@/assets/images/jx1.png'
import jxIcon1 from '@/assets/images/jx1.png'

import tzIcon0 from '@/assets/images/tz1.png'
import tzIcon1 from '@/assets/images/tz1.png'
import wcIcon0 from '@/assets/images/wc0.png'
import wcIcon1 from '@/assets/images/wc1.png'


const text = defineModel('text')
const icon = defineModel('icon')
const status = defineModel('status')



//根据icon类型和status 生成动态class类


let className = computed(() => {
	return icon.value + status.value
})


let statusImgName = computed(() => {
	let imgObj = {
		// 在线
		zx: {
			0: zxIcon0,
			1: zxIcon1
		},
		// 离线
		lx: {
			0: lxIcon0,
			1: lxIcon1
		},
		//故障
		gz: {
			0: gzIcon0,
			1: gzIcon1
		},
		// 进行中
		jx: {
			0: jxIcon0,
			1: jxIcon1
		},
		// 停止
		tz: {
			0: tzIcon0,
			1: tzIcon1
		},
		// 完成
		wc: {
			0: wcIcon0,
			1: wcIcon1
		}
	}
	if (imgObj[icon.value] && imgObj[icon.value][status.value]) {
		return imgObj[icon.value][status.value]
	}
	return ''
})

</script>

<style type="less" scoped>
.item_status {
	width: calc(50% - 5px);
	height: 48px;
	margin-right: 5px;
	background: rgba(46, 55, 66, 0.4);
	border-radius: 10px 10px 10px 10px;
	border: 1px solid #7F7F7F;
	display: flex;
	box-sizing: border-box;
	margin-bottom: 5px;

	.item_status_img {
		width: 50%;

		img {
			margin: 6px 0 0 10px;
		}
	}

	.item_status_text_com_warp {
		width: 50%;

		.item_status_text_content {
			line-height: 30px;
			font-size: 14px;
			font-weight: normal;
			margin: 8px auto;
			color: #c5c5c5;
			background: #4d647d;
			width: 60px;
			border-radius: 15px;
			text-align: center;
		}
	}
}

.item_status.zx1 {
	border-color: rgba(115, 253, 255, 1);

	.item_status_text_content {
		color: rgba(115, 253, 255, 1);
		background-color: rgba(115, 253, 255, 0.1);
	}
}

.item_status.lx1 {
	border-color: rgba(255, 155, 0, 1);

	.item_status_text_content {
		color: rgba(255, 155, 0, 1);
		background-color: rgba(255, 155, 0, 0.1);
	}
}

.item_status.gz1 {
	border-color: rgba(249, 1, 2, 1);

	.item_status_text_content {
		color: rgba(249, 1, 2, 1);
		background-color: rgba(249, 1, 2, 0.1);
	}
}

.item_status.jx1 {
	border-color: rgba(115, 253, 255, 1);

	.item_status_text_content {
		color: rgba(115, 253, 255, 1);
		background-color: rgba(115, 253, 255, 0.1);
	}
}

.item_status.tz1 {
	border-color: rgba(255, 155, 0, 1);

	.item_status_text_content {
		color: rgba(255, 155, 0, 1);
		background-color: rgba(255, 155, 0, 0.1);
	}
}

.item_status.wc1 {
	border-color: rgba(10, 194, 9, 1);

	.item_status_text_content {
		color: rgba(10, 194, 9, 1);
		background-color: rgba(10, 194, 9, 0.1);
	}
}

.item_status.active {
	border-color: #21749d;
}
</style>